export {
  controlView,
  descriptionView,
  errorView,
  itemView,
  labelView,
  rootView,
  validityView,
} from "../../../foldkit/ui/field";
export type {
  ControlViewConfig,
  DescriptionViewConfig,
  ErrorViewConfig,
  FieldState,
  FieldStyle,
  ItemViewConfig,
  LabelViewConfig,
  RootViewConfig,
} from "../../../foldkit/ui/field";

export {
  shadcnFieldControlClasses,
  shadcnFieldDescriptionClasses,
  shadcnFieldErrorClasses,
  shadcnFieldItemClasses,
  shadcnFieldLabelClasses,
  shadcnFieldRootClasses,
  shadcnFieldValidityClasses,
} from "./view";

export {
  fieldControlClasses as shadcnFieldControlClasses,
  fieldDescriptionClasses as shadcnFieldDescriptionClasses,
  fieldErrorClasses as shadcnFieldErrorClasses,
  fieldItemClasses as shadcnFieldItemClasses,
  fieldLabelClasses as shadcnFieldLabelClasses,
  fieldRootClasses as shadcnFieldRootClasses,
  fieldValidityClasses as shadcnFieldValidityClasses,
} from "../../../foldkit/ui/field/view";

import { describe, expect, test } from "vitest";

import * as Field from "./index";

describe("shadcn Field registry view", () => {
  test("reuses the Foldkit Field view contract", () => {
    expect(Field.rootView).toBeTypeOf("function");
    expect(Field.labelView).toBeTypeOf("function");
    expect(Field.controlView).toBeTypeOf("function");
    expect(Field.shadcnFieldControlClasses).toContain("aria-[invalid=true]");
  });
});
